// Core logic behind the "Demo-Projekte generieren" action on
// /admin/demo-daten (and behind scripts/generate-demo-listings.ts, a thin
// CLI wrapper around the same function). See shared.ts for the rationale
// behind using synthetic data instead of scraping real platforms.
//
// Project name/motto/"So leben wir"/"Wen wir suchen" are all generated by
// combining independent word/sentence banks (see the *_STEMS, *_PART_A/B,
// SLOT_* constants below) rather than picked whole from one small fixed
// list — that's what makes every generated listing's text unique (see
// pickUniqueComposed in shared.ts) instead of the same handful of strings
// repeating once more than a few dozen listings exist. Each bank is a set of
// grammatically self-contained fragments (whole sentences, or whole
// compound-noun parts), so any recombination stays coherent — no
// mid-sentence word-swapping that could produce broken German grammar.

import {
  CITIES,
  DEMO_EMAIL_DOMAIN,
  attachRandomPhoto,
  chance,
  jitterCoord,
  maybe,
  pick,
  pickMultiple,
  pickUniqueComposed,
  prisma,
  randomInt,
  randomName,
  randomPhone,
  STREET_NAMES,
} from "./shared";
import { setListingLocation } from "@/lib/geo";

// --- Project name ------------------------------------------------------
// Compound nouns concatenate cleanly in German (no case/gender agreement
// needed within the compound), so stem+suffix is a grammatically bulletproof
// way to generate large numbers of plausible-sounding names; the curated
// phrases add variety in a few other proven patterns ("Zum X", "Die X", ...).

