function buildProjectNameCandidate(): string {
  const base = chance(0.55)
    ? `${pick(NAME_STEMS)}${pick(NAME_SUFFIXES)}`
    : pick(CURATED_NAME_PHRASES);
  return chance(0.2) ? `${base} ${pick(NAME_REGION_TAGS)}` : base;
}

